\widehat{\eta}_{k}(x;B) \defn \frac{\sum_{(X_{t},Y_{t})\in\mathcal{D}_{\mathsf{se}}^{(k)}}Y_{t}\mathds{1}\{X_{t}\in B\}}
{1 \vee \sum_{(X_{t},Y_{t})\in\mathcal{D}_{\mathsf{se}}^{(k)}}\mathds{1}\{X_{t}\in B\}},\quad \forall B\in\mathcal{B}_{l_{i}}. 
\end{align}

}
